), up as (
  update public.routes r
  set outbound = pg_temp.altrans_carry_prices(new.o, r.outbound),
      inbound  = pg_temp.altrans_carry_prices(new.i, r.inbound),
      operator = 'AL-TRANS',
      status   = 'active',
      seats    = coalesce(r.seats, 50),
      currency = 'UAH'
  from new
  where r.carrier_id = 'ec987229-0773-49b9-bac8-69d562a794d1' and r.name = 'Черкаси - Салерно'
  returning r.id
)
insert into public.routes (carrier_id, name, operator, outbound, inbound, status, seats, currency)
select 'ec987229-0773-49b9-bac8-69d562a794d1', 'Черкаси - Салерно', 'AL-TRANS', new.o, new.i, 'active', 50, 'UAH'
from new
where not exists (select 1 from up);

